catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading) {
        return;
    }

    calculateMetroFare();
}


function calculateMetroFare() {

    var source = g_form.getValue('starting_from');
    var destination = g_form.getValue('going_to');
    var journeyType = g_form.getValue('type_of_journey');
    var passengers = parseInt(g_form.getValue('no_of_passengers'), 10);

    if (!source || !destination || !journeyType ||
        isNaN(passengers) || passengers <= 0) {

        g_form.clearValue('amount_for_single_journey');
        g_form.clearValue('amount_including_return');
        return;
    }

    var ga = new GlideAjax('MetroFareUtils');

    ga.addParam('sysparm_name', 'getFare');
    ga.addParam('sysparm_source', source);
    ga.addParam('sysparm_destination', destination);

    ga.getXMLAnswer(function(answer) {

        var fare = parseInt(answer, 10);

        if (isNaN(fare) || fare <= 0) {

            g_form.clearValue('amount_for_single_journey');
            g_form.clearValue('amount_including_return');
            return;
        }

        if (journeyType == '1') {

            var singleAmount = fare * passengers;

            g_form.setValue(
                'amount_for_single_journey',
                singleAmount
            );

            g_form.clearValue(
                'amount_including_return'
            );

        } else if (journeyType == '2') {

            var returnAmount = fare * 2 * passengers;

            g_form.clearValue(
                'amount_for_single_journey'
            );

            g_form.setValue(
                'amount_including_return',
                returnAmount
            );
        }
    });
}
